/**
 * Saves the current scroll position of the {@link #fileListView}.
 * <p>
 * The position is stored as the index of the first visible item and the pixel offset of that
 * item relative to the top of the list. This way the exact scroll position can be restored
 * after the adapter has been replaced (which normally resets the list to the top).
 *
 * @return an array containing the index and the top offset of the first visible item
 * @see #restoreScrollPosition(int[])
 */
private int[] saveScrollPosition() {
    if (fileListView == null) {
        return new int[]{0, 0};
    }
    int index = fileListView.getFirstVisiblePosition();
    View firstVisibleItem = fileListView.getChildAt(0);
    int top = (firstVisibleItem == null) ? 0 : (firstVisibleItem.getTop() - fileListView.getPaddingTop());
    return new int[]{index, top};
}

/**
 * Restores a scroll position previously saved using {@link #saveScrollPosition()}.
 * <p>
 * The restore is posted to the {@link #fileListView}'s message queue so it happens after the
 * new adapter contents have been laid out.
 *
 * @param scrollPosition the position to restore
 * @see #saveScrollPosition()
 */
private void restoreScrollPosition(int[] scrollPosition) {
    if (fileListView == null || scrollPosition == null || scrollPosition.length < 2) {
        return;
    }
    final int index = scrollPosition[0];
    final int top = scrollPosition[1];
    if (index <= 0 && top >= 0) {
        return; // already at the top, nothing to restore
    }
    fileListView.setSelectionFromTop(index, top);
    fileListView.post(() -> fileListView.setSelectionFromTop(index, top));
}

