281	                            }
282	                        } else {
283	                            final FMFile finalArchiveToExtract = archiveToExtract; // 👀
284	                            AlertDialog alertDialog = arrayAdapter.getGenericFileOpDialog(
285	                                    R.string.extract,
286	                                    R.string.op_destination,
