740	    /**
741	     * Shortens the current path by limiting directory paths
742	     * to one char length until the desired maxLength is reached.
743	     *
744	     * @param maxLength max length (chars) of the result
745	     * @return the shortened string
746	     */
747	    @NonNull
748	    private String shortenDirectoryPath(int maxLength) {
749	        final String[] res = {currentDirectory};
750	        ArrayList<String> dirs = new ArrayList<>(Arrays.asList(res[0].split("/")));
751	
752	        for (int i = 0; dirs.size() >= i; i++) {
753	            if (dirs.get(0).isEmpty()) {
754	                dirs.remove(0);
755	                Log.d(TAG, "Element was empty and removed.");
756	            }
757	            res[0] = "";
758	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
759	                dirs.forEach((s) -> res[0] += File.separator + s);
760	            } else { // I could save two lines of code without old versions!
761	                for (String s : dirs) {
762	                    res[0] += File.separator + s;
763	                }
764	            }
765	            if (res[0].length() > maxLength) {
766	                try {
767	                    dirs.set(i, dirs.get(i).substring(0, 1));
768	                } catch (IndexOutOfBoundsException e) {
769	                    Log.d(TAG, "This can happen.", e);
770	                }
771	            }
772	        }
773	
774	        if (res.length > maxLength) {
775	            Log.w(TAG, "Could not shorten the string any further :c");
776	        }
777	        return res[0];
778	    }
