871	    public void finishFileOperation() {
872	        Operation operation = fileOpContext.getFirst();
873	        ArrayList<FMFile> files = fileOpContext.getSecond();
874	        if (!operation.equals(NONE) && !files.isEmpty()) {
875	            if (operation.equals(COPY)) {
876	                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
877	                    files.forEach((f) -> operationUtil.copy(f, null));
878	                } else { // -_-
879	                    for (FMFile f : files) {
880	                        operationUtil.copy(f, null);
881	                    }
882	                }
883	            } else if (operation.equals(MOVE)) {
884	                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
885	                    files.forEach((f) -> operationUtil.move(f, null));
886	                } else { // -_-
887	                    for (FMFile f : files) {
888	                        operationUtil.move(f, null);
889	                    }
890	                }
891	            } else if (operation.equals(EXTRACT)) {
892	                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
893	                    files.forEach((f) -> new ArchiveExtractionTask(this, currentDirectory, f, success -> {
894	                        clearFileOpCache();
895	                        reloadCurrentDirectory();
896	                        if(!success) {
897	                            Toast.makeText(this, R.string.unable_to_extract_archive, Toast.LENGTH_LONG).show();
898	                        }
899	                    }).execute());
900	                } else { // -_-
901	                    for (FMFile f : files) {
902	                        new ArchiveExtractionTask(this, currentDirectory, f, success -> {
903	                            clearFileOpCache();
904	                            reloadCurrentDirectory();
905	                            if(!success) {
906	                                Toast.makeText(this, R.string.unable_to_extract_archive, Toast.LENGTH_LONG).show();
907	                            }
908	                        }).execute();
909	                    }
910	                }
911	            } else if (operation.equals(CREATE_ZIP)) {
912	                AlertDialog alertDialog = arrayAdapter.getGenericFileOpDialog(
913	                        R.string.create_zip_file,
914	                        R.string.op_destination,
915	                        R.drawable.ic_archive_black_24dp,
916	                        R.layout.layout_name_prompt,
917	                        (d) -> {
918	                            String tmpName;
919	                            EditText editText = d.findViewById(R.id.destinationName);
920	                            tmpName = editText.getText().toString();
921	                            if (tmpName.isEmpty() || tmpName.startsWith("/")) {
922	                                Toast.makeText(this, R.string.err_invalid_input_zip, LENGTH_SHORT).show();
