27	public class ArchiveArrayAdapter extends BaseArrayAdapter {
28	
29	    private static final String TAG = ArchiveArrayAdapter.class.getCanonicalName();
30	
31	    private final FMArchive archive;
32	
33	    public ArchiveArrayAdapter(Context context, int resource, List<FMFile> items, FMArchive archive) {
34	        super(context, resource, items);
35	        this.archive = archive;
36	    }
37	
38	    @NonNull
39	    @Override
40	    public View getView(int position, View convertView, @NonNull ViewGroup parent) {
41	        return initUI(getItem(position));
