45	     * Opens a file using the default app.
46	     *
47	     * @param f the file
48	     */
49	    @Override
50	    protected void openFile(FMFile f) {
51	        if(f.isDirectory()) {
52	            activity.loadArchivePath(f.getAbsolutePath(), archive);
53	        } else {
54	            Toast.makeText(activity, R.string.only_browsing_in_archives, Toast.LENGTH_LONG).show();
55	        }
56	    }
