58	    /**
59	     * Initializes the UI for each file.
60	     *
61	     * @param f the file
62	     * @return the initialized UI
63	     */
64	    @Override
65	    protected View initUI(FMFile f) {
66	        assert activity != null;
67	
68	        @SuppressLint("InflateParams") View v = LayoutInflater.from(activity).inflate(R.layout.layout_archive_file, null); // works.
69	
70	        if (f != null) {
71	            TextView fileNameView = v.findViewById(R.id.fileTitle);
72	            ImageView fileImage = v.findViewById(R.id.fileIcon);
73	
74	            final String fileName = f.getName();
75	            if (fileNameView != null) {
76	                int maxLength = Integer.parseInt(new PrefUtils<String>(FILENAME_LENGTH).getValue());
77	                if (fileName.length() >= maxLength) {
78	                    @SuppressLint("SetTextI18n") String output = fileName.substring(0, maxLength - 3) + "...";
79	                    fileNameView.setText(output); //shorten long names
80	                } else {
81	                    fileNameView.setText(fileName);
82	                }
83	            }
84	            if (fileImage != null) {
85	                if (!f.isDirectory()) {
86	                    if (f.isArchive()) {
87	                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_perm_media_black_24dp));
88	                    } else {
89	                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_insert_drive_file_black_24dp));
90	                    }
91	                }
92	            }
93	
94	            v.setOnClickListener(v1 -> openFile(f));
95	            v.setOnCreateContextMenuListener((menu, view, info) -> new ContextMenuUtil(activity, this).initializeContextMenu(f, fileName, menu));
96	            ImageButton contextButton = v.findViewById(R.id.contextMenuButton);
97	            contextButton.setOnClickListener(v1 -> activity.getFileListView().showContextMenuForChild(v));
98	
99	            for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
100	                if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
101	                    v.setBackgroundColor(activity.getColor(R.color.primary));
102	                }
103	            }
104	        }
105	        return v;
106	    }
