41	    public boolean copy(FMFile f, @Nullable AlertDialog d) {
42	        Log.d(TAG, "Starting copy...");
43	
44	        String pathname;
45	
46	        if (d != null) {
47	            EditText editText = d.findViewById(R.id.destinationPath);
48	            pathname = editText.getText().toString();
49	            if (pathname.isEmpty()) {
50	                Toast.makeText(context, R.string.err_empty_input, LENGTH_SHORT).show();
51	                return false;
52	            }
53	        } else {
54	            pathname = context.getCurrentDirectory();
55	        }
56	
57	        File destination = new File(pathname);
58	        final boolean[] success = {false};
59	        if (destination.isDirectory() && !f.isDirectory()) {
60	            destination = new File(destination.getAbsolutePath() + File.separator + f.getName());
61	        }
62	        if (destination.exists()) {
63	            AlertDialog.Builder builder = getFileExistsDialogBuilder(context);
64	            final File tdest = destination; //for lambda
65	            builder.setOnDismissListener(dialogInterface -> success[0] = doCopyNoValidation(f, tdest))
66	                    .setOnCancelListener(dialogInterface -> success[0] = false).show();
67	        } else {
68	            success[0] = doCopyNoValidation(f, destination);
69	        }
70	        context.clearFileOpCache();
71	        context.reloadCurrentDirectory();
72	        return success[0];
73	    }
