135	    public void newDir(File d) {
136	        if (!d.exists()) {
137	            try {
138	                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
139	                    Files.createDirectory(d.toPath());
140	                } else {
141	                    if (!d.mkdirs()) {
142	                        Toast.makeText(context, R.string.err_unable_to_mkdir, Toast.LENGTH_LONG).show();
143	                    }
144	                }
145	            } catch (IOException e) {
146	                Log.e(TAG, context.getString(R.string.err_unable_to_mkdir), e);
147	            }
148	        } else {
149	            Toast.makeText(context, R.string.err_file_exists, Toast.LENGTH_LONG).show();
150	        }
151	    }
