153	    public static boolean deleteNoValidation(FMFile f) {
154	        if(f.isDirectory()){
155	            try {
156	                for (File file : f.getFile().listFiles()) {
157	                    deleteNoValidation(new FMFile(file));
158	                }
159	            } catch (NullPointerException e) {
160	                Log.e(TAG, "No permission for this file.", e);
161	            }
162	        }
163	        return f.getFile().exists() && f.getFile().delete();
164	    }
