166	    public static AlertDialog.Builder getFileExistsDialogBuilder(FileActivity context) {
167	        return new AlertDialog.Builder(context)
168	                .setCancelable(true)
169	                .setTitle(R.string.warn_file_exists_title)
170	                .setMessage(R.string.warn_file_exists_msg)
171	                .setPositiveButton(R.string.yes, (dialogInterface, i) -> dialogInterface.dismiss())
172	                .setNegativeButton(R.string.cancel, (dialogInterface, i) -> dialogInterface.cancel());
173	    }
