175	    private static boolean doCopyNoValidation(FMFile f, File d) {
176	        try {
177	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
178	                Files.copy(f.getFile().toPath(), d.toPath(), StandardCopyOption.REPLACE_EXISTING);
179	            } else {
180	                if (f.getFile().isDirectory()) {
181	                    FileUtils.copyDirectory(f.getFile(), d);
182	                } else {
183	                    FileUtils.copyFile(f.getFile(), d);
184	                }
185	            }
186	            return true;
187	        } catch (IOException e) {
188	            Log.e(TAG, "Unable to copy file!", e);
189	            return false;
190	        }
191	    }
192	
193	    private static boolean doMoveNoValidation(FMFile f, File d) {
194	        try {
195	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
196	                Files.move(f.getFile().toPath(), d.toPath(), StandardCopyOption.REPLACE_EXISTING);
197	            } else {
198	                if (f.getFile().isDirectory()) {
199	                    FileUtils.moveDirectory(f.getFile(), d);
200	                } else {
201	                    FileUtils.moveFile(f.getFile(), d);
202	                }
203	            }
204	            return true;
205	        } catch (IOException e) {
206	            Log.e(TAG, "Unable to move file!", e);
207	            return false;
208	        }
209	    }
