211	    @NonNull
212	    private static String getFullPathForRename(FMFile f, String newName) {
213	        final String[] path = {""};
214	        ArrayList<String> pathSplit = new ArrayList<>(Arrays.asList(f.getFile().getAbsolutePath().split(File.separator)));
215	        pathSplit.remove(pathSplit.size() - 1);
216	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
217	            pathSplit.forEach(s -> path[0] += s + File.separator);
218	        } else { // Ohooold version uuusers, uuupdate youuur phoooooone......
219	            for (String s : pathSplit) {
220	                path[0] += s + File.separator;
221	            }
222	        }
223	        return path[0] + newName;
224	    }
